const origin = new URL("/content/" + namespace, process.env.FIXTURE_URL);
const upstream = await fetch(origin, {
  headers: {
    authorization: "Bearer " + process.env.FIXTURE_TOKEN,
    "accept-language": language,
    "x-function-invocation": invocation,
  },
  cache: "no-store",
  redirect: "error",
  signal: AbortSignal.timeout(8000),
});
if (upstream.status !== 200) throw Error("Origin unavailable");
const contentType = upstream.headers.get("content-type"),
  vary = upstream.headers.get("vary");
// Explicitly support only the fixture variant contract. Unknown dimensions fail closed.
if (
  vary?.toLowerCase().trim() !== "accept-language" ||
  upstream.headers.has("set-cookie")
)
  throw Error("Unsupported origin cache contract");
const headers = new Headers({
  "content-type": contentType,
  "cache-control": "public, max-age=0, must-revalidate",
  "vercel-cdn-cache-control": "public, s-maxage=20",
  "x-function-invocation": invocation,
  "x-origin-fill": upstream.headers.get("x-origin-fill"),
  "x-origin-phase": upstream.headers.get("x-origin-phase"),
});
if (!removeVary(contentType)) headers.set("vary", vary);
return new Response(await upstream.text(), { status: 200, headers });

