export const prefixes = [
  "text/html",
  "text/css",
  "text/js",
  "application/x-javascript",
  "image/x-icon",
];
export function removeVary(contentType) {
  return prefixes.some((prefix) =>
    (contentType || "").trim().toLowerCase().startsWith(prefix),
  );
}
